    private fun observeGlobals() {
        val scene = ControlsState.snapshot
        value(scene, "savedGlobalRefresh").toIntOrNull()?.takeIf{it in supportedRates()}?.let(refresh::observe)
        val savedMode = value(scene, "savedGlobalUperf")
