            if(start)task.run()
            try{return task.get()}
            catch(error:java.util.concurrent.ExecutionException){throw error.cause ?: error}
            finally{synchronized(rulesReadLock){if(rulesRead===task && task.isDone)rulesRead=null}}
        }
    }
