    public ZuiControlService(Context context) {
        mContext = context;
        mPm = context.getPackageManager();
        mDisplayManager = (DisplayManager) context.getSystemService(DisplayManager.class);
        HandlerThread workerThread = new HandlerThread("ZuiControl");
        workerThread.start();
        mWorker = new Handler(workerThread.getLooper());
        mMonitor = new MonitorCollector(context);
        mMonitor.facts=new MonitorCollector.Facts(){
            public String rulesGeneration(){return mObservedRuleGeneration;}
            public String recordPolicy(int user,String pkg){
                AppPolicyStore.State state=mAppPolicies==null?null:mAppPolicies.current;
                if(state==null||!state.users.containsKey(user))return MonitorCollector.Facts.super.recordPolicy(user,pkg);
                AppPolicyStore.Row row=state.resolved(user,pkg);
                return PolicyJson.encode(PolicyJson.map("schema",1,"policyGeneration",state.generation,"refreshHz",row.refreshHz,
                    "uperfMode",row.uperfMode,"gpuMinMHz",row.gpuMinMHz,"gpuMaxMHz",row.gpuMaxMHz,"gpuPolicy",row.gpuPolicy,
                    "zuioptGeneration",rulesGeneration(),"targetProfileSummary",null,"profileSummaryValidity","UNAVAILABLE_NOT_CAPTURED"));
            }
        };
        mUperfScenePolicy = new UperfScenePolicy();
        File dir = new File(DATA_DIR);
        if (!dir.exists() && !dir.mkdirs()) {
            Log.w(TAG, "failed to create " + DATA_DIR);
        }
        mProfileFile = new AtomicFile(new File(PROFILE_FILE));
        // Legacy bytes are consumed only by strict transactional migration.
        try { mAppPolicies = new AppPolicyStore(new PolicyCommand.Disk(new File(DATA_DIR))); }
        catch (Exception e) { mPolicyError = "RECOVERY_REQUIRED:" + e.getClass().getSimpleName(); }
        mRefreshDisableMask = readRefreshDisableMask();
        mObservedRefreshDisableMask = mRefreshDisableMask;
        mRefreshDisabled = mRefreshDisableMask != 0;
        sInstance = this;
        attachInterface(null, DESCRIPTOR);
        registerPeakObserver();
        registerRefreshPropertyObserver();
        registerScreenObserver();
        mUperfScenePolicy.start(mScreenInteractive);
        publishState();
    }

    public static void start(Context context) {
        try {
            ServiceManager.addService("zui_control", new ZuiControlService(context));
            Log.i(TAG, "zui_control service published");
        } catch (Throwable t) {
            Log.e(TAG, "failed to publish zui_control", t);
        }
    }

