    private Map<Integer,Long> policyUsers() throws Exception {
        android.os.UserManager users = mContext.getSystemService(android.os.UserManager.class);
        java.util.List<?> list = (java.util.List<?>) users.getClass().getMethod("getUsers").invoke(users);
        Map<Integer,Long> result = new java.util.TreeMap<>();
        for (Object info : list) {
            int id = info.getClass().getField("id").getInt(info);
            long serial = info.getClass().getField("serialNumber").getInt(info);
            PolicyJson.require(id >= 0 && serial >= 0 && !result.containsValue(serial), "user inventory"); result.put(id, serial);
        }
        return result;
    }

    private String monitorHome(int user) {
        try { return policyHome(user); } catch(Exception e) { return ""; }
    }
    private String policyHome(int user) throws Exception {
        Intent intent = new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME);
        Method resolve=mResolveHomeMethod;
        if(resolve==null){resolve=mPm.getClass().getMethod("resolveActivityAsUser",Intent.class,int.class,int.class);mResolveHomeMethod=resolve;}
        android.content.pm.ResolveInfo result = (android.content.pm.ResolveInfo) resolve.invoke(mPm,intent,PackageManager.MATCH_DEFAULT_ONLY,user);
        return result == null || result.activityInfo == null ? "" : result.activityInfo.packageName;
    }

    private java.util.Set<String> policyExcluded(Map<Integer,Long> users) throws Exception {
        java.util.Set<String> result = new java.util.HashSet<>(Arrays.asList("android", "com.android.systemui", GAME_HELPER_PACKAGE,
                SCREEN_SPLIT_CONTROL_PACKAGE, FREEFORM_SIDEBAR_PACKAGE));
        Method query=mPm.getClass().getMethod("queryIntentServicesAsUser",Intent.class,int.class,int.class);
        for (int user : users.keySet()) {
            String home = policyHome(user); if (!home.isEmpty()) result.add(key(user,home));
            java.util.List<?> inputs=(java.util.List<?>)query.invoke(mPm,new Intent("android.view.InputMethod"),0,user);
            for(Object item:inputs){android.content.pm.ResolveInfo info=(android.content.pm.ResolveInfo)item;
                if(info.serviceInfo!=null&&"android.permission.BIND_INPUT_METHOD".equals(info.serviceInfo.permission))
                    result.add(key(user,info.serviceInfo.packageName));}
        }
        return result;
    }

    private void projectPolicy(AppPolicyStore.State state) {
        mProfiles.clear(); mGpuOverrides.clear(); mGpuGlobalRanges.clear();
        for (Map.Entry<Integer,AppPolicyStore.Row> entry : state.globals.entrySet())
            mProfiles.put(key(entry.getKey(), "default"), new Profile("default", entry.getKey(), entry.getValue().refreshHz, 0, "DISPLAY_ONLY"));
        for (Map.Entry<String,AppPolicyStore.Row> entry : state.apps.entrySet()) {
            int at = entry.getKey().indexOf(':'); int user = Integer.parseInt(entry.getKey().substring(0, at)); String pkg = entry.getKey().substring(at + 1);
            AppPolicyStore.Row row = state.resolved(user,pkg); mProfiles.put(entry.getKey(), new Profile(pkg, user, row.refreshHz, 0, "DISPLAY_ONLY"));
            mGpuOverrides.put(entry.getKey(), new GpuRange(row.gpuMinMHz, row.gpuMaxMHz));
        }
        mGpuGlobalRanges.putAll(state.defaults);
    }

    private String policyRuntimeContext(){
        return mTopResumedState.generation()+"|"+mRawFocusedPackage+"|"+mRawFocusedUserId+"|"+mRawFocusedDisplayId
                +"|"+mRawFocusTransient+"|"+mImeVisible+"|"+mScreenInteractive+"|"+mGpuSystemUi+"|"+readRefreshDisableMask();
    }
    private AppPolicyStore.Owner policyOwner(IBinder remote,boolean force){
        AppPolicyStore.Owner delegate=PolicyCommand.owner(remote,state->applyUnifiedPolicy(state,force));
        return new AppPolicyStore.Owner(){
            public void prepare(AppPolicyStore.State state,String tx)throws Exception{delegate.prepare(state,tx);}
            public void apply(AppPolicyStore.State state,String tx)throws Exception{
                try{delegate.apply(state,tx);mRuntimePolicy=state;mRuntimeContext=policyRuntimeContext();}
                catch(Exception failure){mRuntimePolicy=null;throw failure;}
            }
        };
    }
    private String applyUnifiedPolicy(AppPolicyStore.State state,boolean force) {
        boolean healthy=mPolicyReady&&mAppRequestOwned&&mRenderVoteOwned&&!mAppRequestHandoffPending
                &&mLastApplyError.isEmpty()&&mLastAppliedDisplayId==mRawFocusedDisplayId
                &&mRenderVoteHz==mLastAppliedDisplayHz&&mGpuPolicy.runtimeStatus().equals("READY")
                &&SystemProperties.get(PROP_UPERF_MODE, "").equals(mUperfScenePolicy.mLastRequestedMode);
        boolean full=force||!healthy||!policyRuntimeContext().equals(mRuntimeContext);
        mPolicyReady = true; // Only a validated committed/recovered generation reaches owner apply.
        projectPolicy(state);
        Profile refresh=focusedProfile();
        PolicyRuntimePlan plan=PolicyRuntimePlan.between(mRuntimePolicy,state,refresh.userId,
                refresh.packageName.equals(DEFAULT_SCENE)?"":refresh.packageName,
                mUperfScenePolicy.mSceneUserId,mUperfScenePolicy.mScenePackage,mScreenInteractive,full);
        String applied="unchanged";
        if(plan.refresh){mPolicyRefreshApplies++;PolicyCommand.timing("RUNTIME_REFRESH_APPLY_BEGIN");
            try{applied=applyProfile(refresh,"unifiedPolicy",plan.full);}finally{PolicyCommand.timing("RUNTIME_REFRESH_APPLY_END");}}
        else mPolicyRefreshSkips++;
        if(plan.uperf){mPolicyUperfApplies++;PolicyCommand.timing("RUNTIME_UPERF_APPLY_BEGIN");
            try{mUperfScenePolicy.reconcile("unifiedPolicy",SystemClock.elapsedRealtimeNanos());}finally{PolicyCommand.timing("RUNTIME_UPERF_APPLY_END");}}
        else {mPolicyUperfSkips++;mUperfScenePolicy.updateDesiredMode(state);}
        if ("failed".equals(applied))
            throw new IllegalStateException("policy runtime owner apply failed");
        if (!SystemProperties.get(PROP_UPERF_MODE, "").equals(mUperfScenePolicy.mDesiredMode))
            throw new IllegalStateException("Uperf runtime property ACK");
        PolicyJson.require(AppPolicyStore.mode(mUperfScenePolicy.mDesiredMode), "Uperf desired runtime mode");
        return mUperfScenePolicy.mDesiredMode;
    }

    private void publishPolicySettings() throws Exception {
        Method put = Settings.System.class.getMethod("putStringForUser", android.content.ContentResolver.class, String.class, String.class, int.class);
        AppPolicyStore.State state = mAppPolicies.current;
        for (int user : state.users.keySet()) {
            if(!state.global(user).uperfMode.equals(getSettingForUser(SETTING_UPERF_MODE,user)))
                PolicyJson.require(Boolean.TRUE.equals(put.invoke(null, mContext.getContentResolver(), SETTING_UPERF_MODE, state.global(user).uperfMode, user)), "Uperf global projection");
            retireSensitiveSettings(user);
        }
    }
    private void retireSensitiveSettings(int user)throws Exception{
        UtilityTransport transport=utilities();byte[] receipt=mAppPolicies.disk.read("control-admission.json");
        if(receipt.length!=0){
            Map<String,Object> admission=PolicyJson.object(PolicyJson.parse(receipt));RequestIdentity prior=RequestIdentity.read(admission.get("identity"));
            if(prior.user==user&&java.util.Objects.equals(policyUsers().get(user),prior.serial)){
                if(!transport.request(user).isEmpty()){
                    if(transport.reconcileTerminal(user))Log.i(TAG,"utility_terminal_reconciled user="+user+" id="+prior.id);
                }else{
                    String request=safe(getSettingForUser(SETTING_REQUEST_TEXT,user));
                    if(sha256(request).equals(prior.sha)&&UtilityTransport.fields(request).id.equals(prior.id)){
                        transport.stage(user,request);
                        // Public ACKs never establish private terminal truth.
                    }
                }
            }
        }
        for(String key:new String[]{SETTING_REQUEST_TEXT,"zui_control_request_ack",SETTING_UPERF_RULES,
                "zui_control_log_export","zui_control_zuiopt_state","zui_control_zuiopt_chunk"})
            if(getSettingForUser(key,user)!=null)PolicyJson.require(putSettingForUser(key,null,user),"retire sensitive Settings");
    }

    private synchronized String policyCommand(String requestId, String requestHash, IBinder remote) {
        PolicyCommand.timingRequest.set(requestId);PolicyCommand.timing("SERVER_MONITOR_ACQUIRED");
        Log.i(TIMING_TAG,"id="+requestId+" phase=policy_server_start ns="+SystemClock.elapsedRealtimeNanos());
        long identity = Binder.clearCallingIdentity();
        try {
            PolicyJson.require(mAppPolicies != null, "policy store unavailable");
            AppPolicyStore.Owner owner = policyOwner(remote,"bootstrap".equals(requestId));
            AppPolicyStore.Owner recoveryOwner=policyOwner(remote,true);
            PolicyCommand.timing("POLICY_RECOVERY_BEGIN");mAppPolicies.recover(recoveryOwner);
            new SettingsBackup(mAppPolicies).recover(recoveryOwner,PolicyCommand.rules(remote));
            PolicyCommand.timing("POLICY_RECOVERY_END");PolicyCommand.timing("POLICY_VALIDATION_BEGIN");
            Map<Integer,Long> users = policyUsers(); java.util.Set<String> excluded = new java.util.HashSet<>();
            if (mAppPolicies.current == null) {
                excluded=policyExcluded(users);
                Map<String,Object> raw = PolicyCommand.snapshot(remote);
                byte[] saved = java.util.Base64.getDecoder().decode(PolicyJson.string(raw.get("saved")));
                byte[] perapp = java.util.Base64.getDecoder().decode(PolicyJson.string(raw.get("perapp")));
                byte[] profiles = new File(PROFILE_FILE).exists() ? mProfileFile.readFully() : new byte[0];
                for (String line : new String(profiles, StandardCharsets.UTF_8).split("\\r?\\n")) {
                    String[] columns = line.split("\\|", -1);
                    if (columns.length >= 3 && isTransientPackage(columns[2])) excluded.add(columns[2]);
                }
                for (String line : new String(perapp, StandardCharsets.UTF_8).split("\\r?\\n")) {
                    String[] columns = line.trim().split("\\s+");
                    if (columns.length == 2 && isTransientPackage(columns[0])) excluded.add(columns[0]);
                }
                AppPolicyStore.Migration migration = AppPolicyStore.migrate(profiles, saved, perapp,
                        safe(getSettingForUser( SETTING_UPERF_MODE,0)),
                        safe(getSettingForUser( SETTING_UPERF_RULES,0)), users, excluded);
                mAppPolicies.migrate(migration, profiles, saved, perapp, owner);
            }
            AppPolicyStore.State current = mAppPolicies.current;
            AppPolicyStore.State withUsers = AppPolicyStore.reconcileUsers(current, users);
            if (withUsers != current) {
                // Retire removed identities before publishing an inventory that could admit ID reuse.
                for(int user:current.users.keySet())if(!users.containsKey(user))mMonitor.removeUser(user);
                mAppPolicies.commit(withUsers, owner); current = mAppPolicies.current;
            }
            if (!"bootstrap".equals(requestId)) {
                byte[] raw = mAppPolicies.disk.read("policy-request.json"); Map<String,Object> request = PolicyJson.object(PolicyJson.parse(raw));
                PolicyJson.require(requestId.equals(request.get("id")) && requestHash.equals(request.get("sha")), "authenticated policy request");
                if (request.containsKey("result")) return PolicyJson.string(request.get("result"));
                Map<String,Object> p = PolicyJson.object(request.get("payload"));
                boolean defaultBatch="defaultGpuBatch".equals(p.get("action"));
                if(defaultBatch)PolicyJson.keys(p,"action","userId","generation","ranges");
                else if("save".equals(p.get("action")))
                    PolicyJson.keys(p,"action","userId","packageName","generation","sceneGeneration","scenePackage","scope","value","mode","min","max","gpuPolicy");
                else PolicyJson.keys(p, "action", "userId", "packageName", "generation", "sceneGeneration", "scenePackage", "scope", "value", "mode", "min", "max");
                long expected = PolicyJson.integer(p.get("generation")); int user = AppPolicyStore.user(p.get("userId"));
                if (request.containsKey("targetHash") && current.generation == expected + 1 && PolicyJson.hash(current.bytes()).equals(request.get("targetHash"))) {
                    // The prior invocation committed but lost its reply; recovery above obtained owner ACKs.
                } else {
                    PolicyJson.require(users.containsKey(user), "policy user unavailable");
                    AppPolicyStore.State next;
                    if(defaultBatch){
                        // Authenticated admission already binds caller user and serial. Settings
                        // defaults do not depend on a foreground scene or create App snapshots.
                        next=AppPolicyStore.defaultGpuBatch(current,expected,user,p.get("ranges"));
                    }else{
                        String pkg = PolicyJson.string(p.get("packageName")), action = PolicyJson.string(p.get("action")), scope = PolicyJson.string(p.get("scope"));
                        PolicyJson.require(user == mTopResumedState.stableUserId(), "STALE_SCENE_USER");
                        String home=policyHome(user);
                        boolean global = AppPolicyStore.actionScope(PolicyJson.integer(p.get("sceneGeneration")), PolicyJson.string(p.get("scenePackage")),
                                mTopResumedState.generation(), mTopResumedState.stablePackage(), pkg, scope, home, action, mScreenInteractive);
                        if (!global) {excluded=policyExcluded(users);PolicyJson.require(!excluded.contains(pkg) && !excluded.contains(key(user,pkg)) && !isTransientPackage(pkg) && AppPolicyStore.packageName(pkg), "excluded policy target");}
                        if (pkg.equals(home)) PolicyJson.require(action.equals("refresh") || action.equals("mode"), "HOME global action");
                        if(action.equals("save"))PolicyJson.require(!global&&scope.equals("APP"),"atomic draft APP scope");
                        next = action.equals("save")
                                ?AppPolicyStore.draft(current,expected,user,pkg,PolicyJson.intValue(p.get("value")),
                                        PolicyJson.string(p.get("mode")),PolicyJson.string(p.get("gpuPolicy")),
                                        PolicyJson.intValue(p.get("min")),PolicyJson.intValue(p.get("max")))
                                :AppPolicyStore.change(current, expected, user, pkg, action,
                                PolicyJson.intValue(p.get("value")), PolicyJson.string(p.get("mode")),
                                PolicyJson.intValue(p.get("min")), PolicyJson.intValue(p.get("max")), global);
                    }
                    request.put("previousHash", PolicyJson.hash(current.bytes()));
                    PolicyCommand.timing("POLICY_VALIDATION_END");
                    request.put("targetHash", PolicyJson.hash(next.bytes())); mAppPolicies.disk.write("policy-request.json", PolicyJson.bytes(request));
                    mAppPolicies.commit(next, owner);
                }
                publishPolicySettings();
                String result = "ok=1\ngpuRuntime=" + mGpuPolicy.runtimeStatus() + "\npolicyGeneration=" + mAppPolicies.current.generation;
                if(defaultBatch)result+=AppPolicyStore.gpuDefaultsResult(mAppPolicies.current,user);
                if("save".equals(p.get("action"))){
                    AppPolicyStore.Row saved=mAppPolicies.current.resolved(user,PolicyJson.string(p.get("packageName")));
                    result+="\ngpuPolicy="+saved.gpuPolicy+"\nresolvedGpuMinMHz="+saved.gpuMinMHz+"\nresolvedGpuMaxMHz="+saved.gpuMaxMHz;
                }
                request.put("result", result); mAppPolicies.disk.write("policy-request.json", PolicyJson.bytes(request));
                mPolicyError="";publishState();return result;
            }
            if ("bootstrap".equals(requestId)) {
                String tx = java.util.UUID.randomUUID().toString(); owner.prepare(mAppPolicies.current, tx); owner.apply(mAppPolicies.current, tx); publishPolicySettings();
                byte[] pending = mAppPolicies.disk.read("policy-request.json");
                if (pending.length != 0) {
                    Map<String,Object> request = PolicyJson.object(PolicyJson.parse(pending));
                    if (!request.containsKey("result")) {
                        mAppPolicies.reconcileRequest(PolicyJson.string(request.get("id")),
                                PolicyJson.string(request.get("sha")), owner, () -> { publishPolicySettings(); return null; });
                    }
                }
            }
            if("bootstrap".equals(requestId)){
                mAppPolicies.migrateGpuFollow(owner);publishPolicySettings();
            }
            mPolicyError = ""; publishState(); return "ok=1\ngpuRuntime=" + mGpuPolicy.runtimeStatus() + "\npolicyGeneration=" + mAppPolicies.current.generation;
        } catch (Exception e) {
            mPolicyError = e.getClass().getSimpleName() + ":" + safe(e.getMessage());
            if (mAppPolicies == null || mAppPolicies.recoveryRequired) mPolicyReady = false;
            if (!"bootstrap".equals(requestId)) return reconcilePolicyRequest(requestId, requestHash, remote);
            return "ok=0\nerror=" + mPolicyError;
        } finally { Binder.restoreCallingIdentity(identity);
            Log.i(TIMING_TAG,"id="+requestId+" phase=policy_server_end ns="+SystemClock.elapsedRealtimeNanos());
            PolicyCommand.timing("SERVER_MONITOR_RELEASE");PolicyCommand.timingRequest.remove(); }
    }

    private synchronized String reconcilePolicyRequest(String id, String hash, IBinder remote) {
        long identity = Binder.clearCallingIdentity();
        try {
            PolicyJson.require(mAppPolicies != null, "policy store unavailable");
            PolicyJson.require(!new SettingsBackup(mAppPolicies).busy(), "settings recovery required");
            return mAppPolicies.reconcileRequest(id, hash, policyOwner(remote,true),
                    () -> { publishPolicySettings(); return null; });
        } catch (Exception e) {
            // Not a terminal failure: native retains claim, client retains pending.
            return "pending=1\nrecoveryOutcome=STILL_RECOVERY_REQUIRED";
        } finally { Binder.restoreCallingIdentity(identity); }
    }

    private synchronized String settingsCommand(String action,String argument,IBinder remote){
        long identity=Binder.clearCallingIdentity();
        try{
            PolicyJson.require(mAppPolicies!=null&&mAppPolicies.current!=null,"policy not ready");
            SettingsBackup backup=new SettingsBackup(mAppPolicies);
            AppPolicyStore.Owner owner=policyOwner(remote,true);
            mAppPolicies.recover(owner);backup.recover(owner,PolicyCommand.rules(remote));
            PolicyJson.require(mAppPolicies.current.users.equals(policyUsers()),"settings user inventory changed");
            if("sb_export".equals(action)){
                byte[] archive=backup.export(PolicyCommand.rules(remote),android.os.Build.FINGERPRINT,System.currentTimeMillis());
                mAppPolicies.disk.write("settings-export.zip",archive);
                return "ok=1\nbackupSize="+archive.length+"\nbackupHash="+PolicyJson.hash(archive);
            }
            if("sb_reset".equals(action)){
                PolicyJson.require(argument!=null&&argument.matches("[0-9a-f]{24}"),"reset identity");
                Map<String,Object> admission=PolicyJson.object(PolicyJson.parse(mAppPolicies.disk.read("control-admission.json")));
                RequestIdentity admitted=RequestIdentity.read(admission.get("identity"));
                UtilityTransport.Request request=utilities().admitted(admitted);
                PolicyJson.require(request.command.equals("sb_reset")&&request.packageName.equals(argument)&&request.mode.isEmpty(),"reset admitted identity");
                String path="settings-upload-"+argument;
                if(mAppPolicies.disk.read(path+".json").length==0){
                    AppPolicyStore.Uploads.prune(mAppPolicies.disk,"settings-upload-",".zip",mUploadEpoch,SystemClock.elapsedRealtime(),settingsUploadProtection(),SettingsBackup.LIMIT);
                    AppPolicyStore.Uploads.quota(mAppPolicies.disk,"settings-upload-",".zip",SettingsBackup.LIMIT);
                    byte[] archive=backup.factoryArchive(admitted.user,PolicyCommand.rules(remote),android.os.Build.FINGERPRINT,System.currentTimeMillis());
                    Map<String,Object> meta=PolicyJson.map("transaction",argument,"size",archive.length,"hash",PolicyJson.hash(archive),"factoryResetUser",admitted.user,"factoryResetRequest",admitted.sha);
                    AppPolicyStore.Uploads.begin(meta,mUploadEpoch,SystemClock.elapsedRealtime());
                    mAppPolicies.disk.write(path+".zip",archive);mAppPolicies.disk.write(path+".json",PolicyJson.bytes(meta));
                }
                Map<String,Object> resetMeta=PolicyJson.object(PolicyJson.parse(mAppPolicies.disk.read(path+".json")));
                PolicyJson.require(PolicyJson.integer(resetMeta.get("factoryResetUser"))==admitted.user&&admitted.sha.equals(resetMeta.get("factoryResetRequest")),"reset archive must be server-created for admitted request");
            }
            if("sb_restore".equals(action)||"sb_reset".equals(action)){
                PolicyJson.require(argument!=null&&argument.matches("[0-9a-f]{24}"),"restore identity");
                byte[] archive=mAppPolicies.disk.read("settings-upload-"+argument+".zip");
                Map<String,Object> meta=PolicyJson.object(PolicyJson.parse(mAppPolicies.disk.read("settings-upload-"+argument+".json")));
                PolicyJson.require(PolicyJson.integer(meta.get("size"))==archive.length&&PolicyJson.hash(archive).equals(meta.get("hash")),"restore upload identity");
                byte[] priorJournal=mAppPolicies.disk.read(SettingsBackup.JOURNAL);
                boolean resumed=priorJournal.length!=0&&argument.equals(PolicyJson.object(PolicyJson.parse(priorJournal)).get("transaction"));
                if(!resumed){
                    backup.staged(argument,PolicyJson.hash(archive),mUploadEpoch,SystemClock.elapsedRealtime());
                    PolicyJson.require("sb_reset".equals(action)||PolicyJson.hash(archive).equals(meta.get("confirmedHash")),"restore requires inspected confirmation");
                }
                Map<String,byte[]> entries=SettingsBackup.validate(archive,policyUsers());
                AppPolicyStore.State target=AppPolicyStore.State.parse(entries.get("policy.json"));
                java.util.Set<String> excluded=policyExcluded(target.users);
                for(String key:target.apps.keySet()){
                    String pkg=key.substring(key.indexOf(':')+1);
                    PolicyJson.require(!excluded.contains(pkg)&&!excluded.contains(key)&&!isTransientPackage(pkg),"restore excluded policy target");
                }
                backup.restore(archive,argument,owner,PolicyCommand.rules(remote));
                try{mObservedRuleGeneration=PolicyJson.string(PolicyCommand.rules(remote).snapshot().get("generation"));}
                catch(Exception unavailable){mObservedRuleGeneration="UNAVAILABLE";}
                meta.put("completed",true);mAppPolicies.disk.write("settings-upload-"+argument+".json",PolicyJson.bytes(meta));
                mAppPolicies.pruneCompleted();
            }else PolicyJson.require("sb_recover".equals(action),"settings action");
            publishPolicySettings();mMonitor.invalidatePower();return "ok=1\nsettingsPhase="+
                PolicyJson.string(PolicyJson.object(PolicyJson.parse(mAppPolicies.disk.read(SettingsBackup.JOURNAL))).get("phase"));
        }catch(Exception e){
            if(e instanceof IllegalArgumentException&&"sb_restore".equals(action)&&argument!=null&&argument.matches("[0-9a-f]{24}")){
                try{
                    byte[] raw=mAppPolicies.disk.read(SettingsBackup.JOURNAL);
                    boolean referenced=raw.length!=0&&argument.equals(PolicyJson.object(PolicyJson.parse(raw)).get("transaction"));
                    if(!referenced){
                        String path="settings-upload-"+argument+".json";Map<String,Object> meta=PolicyJson.object(PolicyJson.parse(mAppPolicies.disk.read(path)));
                        meta.put("transferState","REJECTED");mAppPolicies.disk.write(path,PolicyJson.bytes(meta));
                    }
                }catch(Exception uncertain){ /* Retain evidence if durable rejection cannot be established. */ }
            }
            return "ok=0\nerror=settings:"+e.getClass().getSimpleName()+":"+safe(e.getMessage());
        }
        finally{Binder.restoreCallingIdentity(identity);}
    }
    private String settingsTransport(String action,String argument,int user)throws Exception{
        PolicyJson.require(mAppPolicies!=null&&mAppPolicies.current!=null,"policy not ready");
        SettingsBackup backup=new SettingsBackup(mAppPolicies);
        if(action.equals("preferencesRead")||action.equals("preferencesWrite")){
            PolicyJson.require(!backup.busy(),"settings recovery required");
            Map<Integer,Long> inventory=policyUsers();
            Map<String,Object> prefs=PolicyJson.object(PolicyJson.parse(backup.prefs(inventory)));
            for(Object item:PolicyJson.array(prefs.get("users"))){Map<String,Object> row=PolicyJson.object(item);
                if(PolicyJson.integer(row.get("userId"))!=user)continue;
                if(action.equals("preferencesWrite")){
                    Map<String,Object> value=PolicyJson.object(PolicyJson.parse(argument.getBytes(StandardCharsets.UTF_8)));
                    PolicyJson.keys(value,"circle_x","circle_y");row.putAll(value);
                    mAppPolicies.disk.write(SettingsBackup.PREFS,SettingsBackup.preferences(PolicyJson.bytes(prefs),inventory));
                }
                return PolicyJson.encode(row);
            }
            throw new IllegalArgumentException("preference user unavailable");
        }
        PolicyJson.require(user==0,"settings backup primary user required");
        if(action.equals("backupRead")){
            String[] fields=argument.split(":",-1);PolicyJson.require(fields.length==2,"export identity");
            byte[] archive=mAppPolicies.disk.read("settings-export.zip");PolicyJson.require(PolicyJson.hash(archive).equals(fields[0]),"export changed");
            int offset=Integer.parseInt(fields[1]);PolicyJson.require(offset>=0&&offset<archive.length,"export offset");
            return java.util.Base64.getEncoder().encodeToString(Arrays.copyOfRange(archive,offset,Math.min(offset+8192,archive.length)));
        }
        PolicyJson.require(!backup.busy(),"settings restore recovery required");
        Map<String,Object> request=PolicyJson.object(PolicyJson.parse(argument.getBytes(StandardCharsets.UTF_8)));
        String tx=PolicyJson.string(request.get("transaction"));PolicyJson.require(tx.matches("[0-9a-f]{24}"),"settings upload transaction");
        String path="settings-upload-"+tx;
        if(action.equals("backupInspect")||action.equals("backupConfirm")){
            PolicyJson.keys(request,"transaction","hash");String digest=PolicyJson.string(request.get("hash"));
            if(action.equals("backupInspect"))return PolicyJson.encode(backup.inspect(tx,digest,mUploadEpoch,SystemClock.elapsedRealtime()));
            backup.confirm(tx,digest,mUploadEpoch,SystemClock.elapsedRealtime());return "ok=1";
        }
        if(action.equals("backupAbort")){
            PolicyJson.keys(request,"transaction");
            PolicyJson.require(!settingsUploadProtection().contains(tx),"restore already admitted");
            Map<String,Object> meta=PolicyJson.object(PolicyJson.parse(mAppPolicies.disk.read(path+".json")));
            AppPolicyStore.Uploads.active(meta,mUploadEpoch,SystemClock.elapsedRealtime());
            meta.put("transferState","REJECTED");mAppPolicies.disk.write(path+".json",PolicyJson.bytes(meta));return "ok=1";
        }
        if(action.equals("backupBegin")){
            PolicyJson.keys(request,"transaction","size","hash");long size=PolicyJson.integer(request.get("size"));
            PolicyJson.require(size>0&&size<=SettingsBackup.LIMIT&&PolicyJson.string(request.get("hash")).matches("[0-9a-f]{64}"),"settings upload metadata");
            AppPolicyStore.Uploads.prune(mAppPolicies.disk,"settings-upload-",".zip",mUploadEpoch,SystemClock.elapsedRealtime(),settingsUploadProtection(),SettingsBackup.LIMIT);
            byte[] old=mAppPolicies.disk.read(path+".json");
            if(old.length==0){
                AppPolicyStore.Uploads.quota(mAppPolicies.disk,"settings-upload-",".zip",SettingsBackup.LIMIT);
                AppPolicyStore.Uploads.begin(request,mUploadEpoch,SystemClock.elapsedRealtime());
                // Metadata first: an interrupted begin is an explicitly expirable transaction, not an orphan payload.
                mAppPolicies.disk.write(path+".json",PolicyJson.bytes(request));mAppPolicies.disk.write(path+".zip",new byte[0]);
            }else{
                Map<String,Object> meta=PolicyJson.object(PolicyJson.parse(old));AppPolicyStore.Uploads.active(meta,mUploadEpoch,SystemClock.elapsedRealtime());
                PolicyJson.require(PolicyJson.integer(meta.get("size"))==size&&meta.get("hash").equals(request.get("hash")),"settings upload immutable identity");
            }
        }else{
            PolicyJson.require(action.equals("backupChunk"),"settings transport action");PolicyJson.keys(request,"transaction","offset","data");
            Map<String,Object> meta=PolicyJson.object(PolicyJson.parse(mAppPolicies.disk.read(path+".json")));
            AppPolicyStore.Uploads.active(meta,mUploadEpoch,SystemClock.elapsedRealtime());
            PolicyJson.require(!meta.containsKey("inspectedHash"),"inspected upload immutable");
            byte[] current=mAppPolicies.disk.read(path+".zip"),chunk=java.util.Base64.getDecoder().decode(PolicyJson.string(request.get("data")));
            int offset=PolicyJson.intValue(request.get("offset"));PolicyJson.require(offset>=0&&offset<=current.length&&chunk.length>0&&chunk.length<=8192
                &&offset+chunk.length<=PolicyJson.integer(meta.get("size")),"settings upload bound");
            if(offset<current.length)PolicyJson.require(offset+chunk.length<=current.length&&Arrays.equals(chunk,Arrays.copyOfRange(current,offset,offset+chunk.length)),"conflicting upload replay");
            else {byte[] next=Arrays.copyOf(current,current.length+chunk.length);System.arraycopy(chunk,0,next,current.length,chunk.length);mAppPolicies.disk.write(path+".zip",next);}
        }
        return "ok=1";
    }
    private java.util.Set<String> settingsUploadProtection()throws Exception{
        java.util.Set<String> ids=new java.util.HashSet<>();byte[] raw=mAppPolicies.disk.read(SettingsBackup.JOURNAL);
        if(raw.length!=0)ids.add(PolicyJson.string(PolicyJson.object(PolicyJson.parse(raw)).get("transaction")));
        raw=mAppPolicies.disk.read("control-admission.json");
        if(raw.length!=0){Map<String,Object> admission=PolicyJson.object(PolicyJson.parse(raw));RequestIdentity identity=RequestIdentity.read(admission.get("identity"));
            if(identity.user==0){String request=utilities().request(0);if(!request.isEmpty()&&sha256(request).equals(identity.sha)){
                String transaction=utilities().admitted(identity).restoreTransaction();
                if(!transaction.isEmpty())ids.add(transaction);
            }}
        }
        return ids;
    }

    private synchronized String setGlobalGpuRange(String mode, int userId, int min, int max) {
        if (userId < 0 || userId != Binder.getCallingUid() / 100000 || !isUperfMode(mode)) {
            return "ok=0\nerror=invalid_gpu_mode";
        }
        GpuRange value = new GpuRange(min, max);
        synchronized (mUperfScenePolicy) {
            Map<String, GpuRange> previous = new HashMap<>(mGpuGlobalRanges);
            for (String level : new String[] {"powersave", "balance", "performance", "fast"}) {
                String modeKey = key(userId, level);
                if (!mGpuGlobalRanges.containsKey(modeKey)) mGpuGlobalRanges.put(modeKey, GpuRange.defaults(level));
            }
            String k = key(userId, mode);
            mGpuGlobalRanges.put(k, value);
            if (!saveProfiles()) {
                mGpuGlobalRanges.clear(); mGpuGlobalRanges.putAll(previous);
                return "ok=0\nerror=gpu_global_save";
            }
            mUperfScenePolicy.refreshGpu();
        }
        return "ok=1";
    }

    private synchronized String monitorCommand(Parcel data) throws RemoteException {
        String command = data.readString();
        int callerUser = Binder.getCallingUid() / 100000;
        if ("unregister".equals(command)){mMonitor.unregister(data.readStrongBinder());return "ok=1";}
        IBinder listener="register".equals(command)?data.readStrongBinder():null;
        String argument = ("recordRead".equals(command) || "recordDelete".equals(command) || "recordStart".equals(command) || command.startsWith("backup") || command.startsWith("preferences") || command.startsWith("analysis")) ? data.readString() : "";
        long identity = Binder.clearCallingIdentity();
        try {
            {
                try{Map<Integer,Long> inventory=policyUsers();
                    PolicyJson.require(mAppPolicies!=null&&mAppPolicies.current!=null&&inventory.containsKey(callerUser)
                        &&(!mAppPolicies.current.users.containsKey(callerUser)
                        ||java.util.Objects.equals(mAppPolicies.current.users.get(callerUser),inventory.get(callerUser))),
                        "user inventory not admitted");}
                catch(Exception e){return "ok=0\nerror=user_inventory_not_admitted";}
            }
            if(command.startsWith("backup")||command.startsWith("preferences")){
                try{return settingsTransport(command,argument,callerUser);}catch(Exception e){return "ok=0\nerror="+safe(e.getMessage());}
            }
            if("analysisStart".equals(command)){
                try{
                    String target=PolicyJson.string(PolicyJson.object(PolicyJson.parse(argument.getBytes(StandardCharsets.UTF_8))).get("package"));
                    java.util.Set<String> excluded=policyExcluded(java.util.Collections.singletonMap(callerUser,policyUsers().get(callerUser)));
                    PolicyJson.require(validPackage(target)&&!excluded.contains(target)&&!excluded.contains(key(callerUser,target))&&!isTransientPackage(target),"invalid analysis target");
                    Context userContext=(Context)Context.class.getMethod("createContextAsUser",android.os.UserHandle.class,int.class)
                        .invoke(mContext,android.os.UserHandle.getUserHandleForUid(callerUser*100000),0);
                    userContext.getPackageManager().getApplicationInfo(target,0);
                }catch(Exception e){return "ok=0\nerror=invalid_analysis_target";}
            }
            refreshMonitor();
            if("register".equals(command))mMonitor.register(listener,callerUser);
            String result = mMonitor.command("register".equals(command) ? "state" : command,
                    callerUser, argument == null ? "" : argument);
            if (result.startsWith("ok=1") && ("full".equals(command) || "fps".equals(command))) {
                // Existing system-server authority, only after the authenticated direct user action.
                try { mContext.sendBroadcastAsUser(new Intent(Intent.ACTION_CLOSE_SYSTEM_DIALOGS),
                        android.os.UserHandle.getUserHandleForUid(callerUser * 100000)); }
                catch (RuntimeException e) { Log.w(TAG, "monitor notification collapse unavailable", e); }
            }
            return result;
        } finally { Binder.restoreCallingIdentity(identity); }
    }

    private synchronized void refreshMonitor() {
        String pkg = mTopResumedState.stablePackage();
        int user = mTopResumedState.stableUserId();
        android.app.KeyguardManager lock = mContext.getSystemService(android.app.KeyguardManager.class);
        boolean locked=lock==null||lock.isKeyguardLocked();
        PowerManager power=mContext.getSystemService(PowerManager.class);
        boolean interactive=mScreenInteractive&&power!=null&&power.isInteractive();
        boolean eligible = interactive && !locked
                && !SystemProperties.getBoolean(PROP_GLOBAL_DISABLE, false);
        // Visibility follows screen lifecycle; recording still requires the actual target App.
        // Keep editableScene, Refresh and Uperf transient-focus policy unchanged.
        String home=eligible?monitorHome(user):"";
        boolean recordEligible = eligible && !pkg.isEmpty() && !home.isEmpty() && !pkg.equals(home)
                && (!isTransientPackage(pkg) || "com.zui.zuicontrol".equals(pkg));
        mMonitor.scene(pkg, user, eligible, recordEligible && mMonitorTaskId>=0,
                !interactive?"SCREEN_OFF":locked?"LOCKED":"VISIBILITY_BLOCKED",mMonitorTaskId,
                eligible && mMonitorTaskId>=0 && !pkg.isEmpty() && !mRawFocusTransient && !mImeVisible
                        && pkg.equals(mRawFocusedPackage) && user==mRawFocusedUserId
                        && mRawFocusedDisplayId==Display.DEFAULT_DISPLAY);
    }

    private synchronized String setGpuRange(String pkg, int userId, int min, int max) {
        if (userId < 0 || userId != Binder.getCallingUid() / 100000
                || !validPackage(pkg) || !packageExists(pkg) || isGpuTransientPackage(pkg)) {
            return "ok=0\nerror=invalid_gpu_target";
        }
        GpuRange value = min == 0 && max == 0 ? null : new GpuRange(min, max);
        synchronized (mUperfScenePolicy) {
            String k = key(userId, pkg);
            GpuRange previous = mGpuOverrides.get(k);
            if (value == null) mGpuOverrides.remove(k); else mGpuOverrides.put(k, value);
            if (!saveProfiles()) {
                if (previous == null) mGpuOverrides.remove(k); else mGpuOverrides.put(k, previous);
                return "ok=0\nerror=gpu_profile_save";
            }
            mUperfScenePolicy.refreshGpu();
        }
        return "ok=1\ngpuOverride=" + (value == null ? "NONE" : min + "|" + max);
    }

