                        + " propertyAckNs=" + propertyAckNanos
                        + " desired=" + mDesiredMode
                        + " scene=" + mScenePackage
                        + " reason=" + mLastReason
                        + " applyCount=" + mApplyCount);
            } catch (Throwable t) {
                mLastReason = reason + ":propertySetFailed";
                Log.w(TAG, "Uperf mode property set failed", t);
            }
        }

        synchronized void refreshGpu() {
            // Window SystemUI and profile edits affect GPU only, never CPU mode.
            boolean gpuEligible = mPolicyReady && mStarted && !mGpuSystemUi && !mScenePackage.isEmpty()
                    && !isGpuTransientPackage(mScenePackage);
