    private java.util.List<Object> appPolicyRows(AppPolicyStore.State state,int user){
        java.util.List<Object> rows=new java.util.ArrayList<>();
        for(Map.Entry<String,AppPolicyStore.Row> e:state.apps.entrySet())if(e.getKey().startsWith(user+":")){
            String pkg=e.getKey().substring(e.getKey().indexOf(':')+1);
            rows.add(PolicyJson.map("packageName",pkg,"persisted",e.getValue().json(state.schema),
                    "effective",state.resolved(user,pkg).json(state.schema)));
        }
        return rows;
    }
    // Read-only observation of the native authority. Invalidated BEFORE any admitted writer.
    private volatile String mObservedRuleGeneration="UNAVAILABLE";
    private long mRulesObservationEpoch;
    private synchronized void invalidateRulesObservation(){mRulesObservationEpoch++;mObservedRuleGeneration="UNAVAILABLE";}
    private synchronized void observeRules(String state){
        String generation="UNAVAILABLE";
        for(String line:state.split("\n"))if(line.matches("generation=g[0-9a-f]{24}"))generation=line.substring(11);
        mRulesObservationEpoch++;mObservedRuleGeneration=generation;
    }
    private static boolean rulesWriter(String command){
        return java.util.Arrays.asList("zo_commit","zo_rollback","zo_restore_app","zo_enable","zo_disable","sb_restore","sb_reset").contains(command);
    }
    /** Same admitted caller/user and canonical native owner; no durable request slot or writer lane. */
    private String rulesRead(String argument){
        final int user=Binder.getCallingUid()/100000;long token=Binder.clearCallingIdentity();
        try{
            Map<Integer,Long> inventory=policyUsers();AppPolicyStore.State current=mAppPolicies==null?null:mAppPolicies.current;
            PolicyJson.require(current!=null&&inventory.containsKey(user)
                    &&(!current.users.containsKey(user)||java.util.Objects.equals(current.users.get(user),inventory.get(user))),"user_inventory_not_admitted");
            final long epoch;synchronized(this){epoch=mRulesObservationEpoch;}
            String result=mZuioptScene.readRules(argument);
            String state=result;
            if(!"state".equals(argument)){
                String[] parts=result.split("\n",-1);
                PolicyJson.require(parts.length==6&&parts[0].equals("ZUIOPT_READ_SNAPSHOT_V1")&&parts[1].startsWith("state="),"rules snapshot frame");
                state=new String(java.util.Base64.getDecoder().decode(parts[1].substring(6)),StandardCharsets.UTF_8);
            }
            PolicyJson.require(state.length()<=4608&&state.contains("\nrules_read_transport=DAEMON_SNAPSHOT_V1\n"),"rules read state");
            synchronized(this){
                // Durable admission closes the admitted-before-native-lock window.
                // Epoch changes on invalidation AND terminal observation reject older in-flight reads.
                byte[] admission=mAppPolicies.disk.read("control-admission.json");
                boolean settled=admission.length==0||Boolean.TRUE.equals(PolicyJson.object(PolicyJson.parse(admission)).get("terminal"));
                if(epoch==mRulesObservationEpoch&&settled)observeRules(state);
            }
            return "ok=1\nresultCategory=AUTHORITATIVE_READ_ONLY\nreadData="+result;
        }catch(ZuioptSceneAuthority.OwnerAbsentException absent){return "ok=0\nerror=rules_read_owner_absent";}
        catch(Exception e){return "ok=0\nerror=rules_read:"+e.getClass().getSimpleName()+":"+safe(e.getMessage());}
        finally{Binder.restoreCallingIdentity(token);}
    }
    private String requestRefused(int user,String id,String error){
        String category="INDETERMINATE_OR_IN_PROGRESS";
        try{
            if(!validRequestId(id))category="DEFINITIVE_NOT_ADMITTED";
            else if(mAppPolicies!=null){
                boolean seen=false;
                for(String file:new String[]{"control-admission.json","policy-request.json","policy-request-"+id+".json"}){
                    byte[] data=mAppPolicies.disk.read(file);if(data.length==0)continue;
                    Map<String,Object> row=PolicyJson.object(PolicyJson.parse(data));
                    if(row.containsKey("identity"))seen|=id.equals(RequestIdentity.read(row.get("identity")).id);
                    else seen|=id.equals(row.get("id"));
                }
                if(!seen)category="DEFINITIVE_NOT_ADMITTED";
            }
        }catch(Exception uncertain){ /* Unreadable admission evidence is never permission to forget a request. */ }
        return "ok=0\nerror="+error+"\nresultCategory="+category;
    }
    /** Exact private reads share the disk's short AtomicFile lock, not the policy transaction monitor. */
    private String utilityRead(String action,String argument){
        final int user=Binder.getCallingUid()/100000;long token=Binder.clearCallingIdentity();
        try{
            Map<Integer,Long> inventory=policyUsers();
            AppPolicyStore.State state=mAppPolicies==null?null:mAppPolicies.current;
            PolicyJson.require(state!=null&&inventory.containsKey(user)
                    &&(!state.users.containsKey(user)||java.util.Objects.equals(state.users.get(user),inventory.get(user))),"user_inventory_not_admitted");
            String result,category="INDETERMINATE_OR_IN_PROGRESS";
            UtilityTransport transport=new UtilityTransport(mAppPolicies.disk,inventory);
            if("ack".equals(action)){
                PolicyJson.require(validRequestId(argument),"utility request ID");result=transport.ack(user,argument);
                String[] ack=result.split("\\|",-1);if(ack.length==4&&("done".equals(ack[1])||"failed".equals(ack[1])))category="ADMITTED_TERMINAL";
            }else{
                PolicyJson.require("result".equals(action),"utility read action");String[] fields=argument.split("\\|",-1);
                PolicyJson.require(fields.length==2&&validRequestId(fields[0]),"utility result request");
                result=transport.result(user,fields[0],fields[1]);category="ADMITTED_TERMINAL";
            }
            return "ok=1\nresultCategory="+category+"\ndata="+java.util.Base64.getEncoder().encodeToString(result.getBytes(StandardCharsets.UTF_8));
        }catch(Exception e){return "ok=0\nerror=utility:"+e.getClass().getSimpleName()+":"+safe(e.getMessage())+"\nresultCategory=INDETERMINATE_OR_IN_PROGRESS";}
        finally{Binder.restoreCallingIdentity(token);}
    }
    private synchronized String utilityCommand(String action,String argument){
        final int user=Binder.getCallingUid()/100000;
        long token=Binder.clearCallingIdentity();String id="";
        try{
            Map<Integer,Long> inventory=policyUsers();
            PolicyJson.require(mAppPolicies!=null&&mAppPolicies.current!=null&&inventory.containsKey(user)
                    &&(!mAppPolicies.current.users.containsKey(user)||java.util.Objects.equals(mAppPolicies.current.users.get(user),inventory.get(user))),"user_inventory_not_admitted");
            UtilityTransport transport=utilities();String result,category="INDETERMINATE_OR_IN_PROGRESS";
            if("submit".equals(action)){
                id=argument==null?"":argument.split("\\|",-1)[0];
                UtilityTransport.Request request=UtilityTransport.fields(argument);
                if(rulesWriter(request.command))invalidateRulesObservation();
                if(user!=0&&((request.command.startsWith("sb_")&&!request.command.equals("sb_reset"))||request.command.equals("export_logs")))
                    return requestRefused(user,id,request.command.startsWith("sb_")?"settings_primary_user_required":"diagnostic_primary_user_required");
                transport.stage(user,argument);
                return notifyControlRequest(id,sha256(argument),user);
            }else if("ack".equals(action)){
                PolicyJson.require(validRequestId(argument),"utility request ID");result=transport.ack(user,argument);
                String[] ack=result.split("\\|",-1);if(ack.length==4&&("done".equals(ack[1])||"failed".equals(ack[1])))category="ADMITTED_TERMINAL";
            }else if("result".equals(action)){
                String[] fields=argument.split("\\|",-1);PolicyJson.require(fields.length==2&&validRequestId(fields[0]),"utility result request");
                result=transport.result(user,fields[0],fields[1]);category="ADMITTED_TERMINAL";
            }else if("appPolicies".equals(action)){
                PolicyJson.require(argument.isEmpty(),"appPolicies argument");
                AppPolicyStore.State state=mAppPolicies.current;java.util.List<Object> rows=appPolicyRows(state,user);
                result=new String(PolicyJson.bytes(PolicyJson.map("schema",state.schema,"userId",user,
                        "generation",state.generation,"apps",rows)),StandardCharsets.UTF_8);
            }else{
                PolicyJson.require("uperfRules".equals(action)&&"".equals(argument),"utility action");
                StringBuilder rows=new StringBuilder();
                for(Map.Entry<String,AppPolicyStore.Row> row:mAppPolicies.current.apps.entrySet())if(row.getKey().startsWith(user+":")){
                    if(rows.length()>0)rows.append('\n');rows.append(row.getKey().substring(row.getKey().indexOf(':')+1)).append('|').append(row.getValue().uperfMode);
                }
                result=rows.toString();
            }
            return "ok=1\nresultCategory="+category+"\ndata="+java.util.Base64.getEncoder().encodeToString(result.getBytes(StandardCharsets.UTF_8));
        }catch(Exception e){
            String reason=safe(e.getMessage());
            if("submit".equals(action)&&java.util.Arrays.asList("request_transport_bound","request_payload_mismatch","request_busy","policy_store_unavailable").contains(reason))
                return requestRefused(user,id,reason);
            return "ok=0\nerror=utility:"+e.getClass().getSimpleName()+":"+reason+"\nresultCategory=INDETERMINATE_OR_IN_PROGRESS";
        }finally{Binder.restoreCallingIdentity(token);}
    }
    private RequestIdentity authenticatedPolicyIdentity(String id,String hash,String sequence,int user)throws Exception {
        PolicyJson.require(validRequestId(id)&&validSha256(hash),"policy identity bounds");
        Map<String,Object> request=PolicyJson.object(PolicyJson.parse(mAppPolicies.disk.read("policy-request.json")));
        if(!id.equals(request.get("id")))request=PolicyJson.object(PolicyJson.parse(mAppPolicies.disk.read("policy-request-"+id+".json")));
        RequestIdentity identity=RequestIdentity.read(request.get("identity"));
        identity.verify(user,id,hash,sequence,policyUsers());return identity;
    }

    private synchronized String commandTransport(String id, String hash, String sequence,int user,String kick,
            String action, String value) throws Exception {
        PolicyJson.require(validRequestId(id) && validSha256(hash)
                && sequence != null && sequence.length() <= 64
                && id.equals(SystemProperties.get(PROP_COMMAND_ID, ""))
                && hash.equals(SystemProperties.get(PROP_COMMAND_SHA256, ""))
                && kick!=null&&kick.equals(SystemProperties.get(PROP_COMMAND_SEQ, "")), "admitted transport identity");
        long identity=Binder.clearCallingIdentity();
        try {
            Map<String,Object> admission=PolicyJson.object(PolicyJson.parse(mAppPolicies.disk.read("control-admission.json")));
            RequestIdentity admitted=RequestIdentity.read(admission.get("identity"));
            admitted.verify(user,id,hash,sequence,policyUsers());
            PolicyJson.require(kick.startsWith("u"+user+"_"+sequence+"_"),"kick user/sequence");
            UtilityTransport transport=utilities();String request=transport.request(user);
            PolicyJson.require(request.length()<=262144 && sha256(request).equals(hash), "transport request hash");
            UtilityTransport.Request parsed=UtilityTransport.fields(request);
            PolicyJson.require(id.equals(parsed.id), "transport request");
            if("namespace".equals(action)){PolicyJson.require("".equals(value),"namespace argument");return "user-shell-"+user+"-"+admitted.serial;}
            if ("read".equals(action)) { PolicyJson.require("".equals(value),"read argument"); return request; }
            if("readAck".equals(action)){PolicyJson.require("".equals(value),"ACK read argument");return transport.ack(user,id);}
            if(action.startsWith("result:")){transport.publish(admitted,action.substring(7),value);return "ok=1";}
            PolicyJson.require("ack".equals(action) && value!=null && value.length()<=8192
                    && value.indexOf('\n')<0 && value.indexOf('\r')<0, "transport ACK");
            String[] ack=value.split("\\|",-1);
            PolicyJson.require(ack.length==4 && id.equals(ack[0]) && parsed.command.equals(ack[2])
                    && ("processing".equals(ack[1])||"done".equals(ack[1])||"failed".equals(ack[1])), "ACK identity/state");
            transport.acknowledge(admitted,value);
            transport.reconcileTerminal(user);
            if("done".equals(ack[1])&&(parsed.command.equals("zo_state")||parsed.command.equals("zo_commit")||parsed.command.equals("zo_rollback")||parsed.command.equals("zo_restore_app")||parsed.command.equals("zo_enable")||parsed.command.equals("zo_disable")))
                observeRules(transport.result(user,id,"rulesState"));
            return "ok=1";
        } finally { Binder.restoreCallingIdentity(identity); }
    }

    private synchronized String notifyControlRequest(String requestId, String requestSha256) {
        return notifyControlRequest(requestId,requestSha256,Binder.getCallingUid()/100000);
    }
    private String notifyControlRequest(String requestId,String requestSha256,int policyCallerUser){
        long binderEnterNanos = SystemClock.elapsedRealtimeNanos();
        String id = safe(requestId).trim();
        String sha256 = safe(requestSha256).trim();
        Log.i(TIMING_TAG, "id=" + id + " phase=T1 ns=" + binderEnterNanos);
        if (!validRequestId(id)) {
            return requestRefused(policyCallerUser,id,"invalid_request_id");
        }
        if (!validSha256(sha256)) {
            return "ok=0\nerror=invalid_request_sha256";
        }
        long identity = Binder.clearCallingIdentity();
        try {
            String requestText = utilities().request(policyCallerUser);
            if (requestText == null || requestText.getBytes(StandardCharsets.UTF_8).length > 131072)
                return requestRefused(policyCallerUser,id,"request_transport_bound");
            UtilityTransport.Request request = UtilityTransport.fields(safe(requestText));
            if (!id.equals(request.id) || !sha256(safe(requestText)).equals(sha256)) {
                return requestRefused(policyCallerUser,id,"request_payload_mismatch");
            }
            if(request.command.startsWith("sb_")&&policyCallerUser!=0)return requestRefused(policyCallerUser,id,"settings_primary_user_required");
            PolicyJson.require(mAppPolicies!=null,"request store unavailable");
            Map<Integer,Long> inventory=policyUsers();
            PolicyJson.require(inventory.containsKey(policyCallerUser),"request user unavailable");
            RequestIdentity admitted=new RequestIdentity(policyCallerUser,inventory.get(policyCallerUser),id,sha256,
                    java.util.UUID.randomUUID().toString().replace("-",""));
            byte[] oldAdmission=mAppPolicies.disk.read("control-admission.json");
            if(oldAdmission.length!=0){
                Map<String,Object> old=PolicyJson.object(PolicyJson.parse(oldAdmission));
                RequestIdentity prior=RequestIdentity.read(old.get("identity"));
                if(id.equals(prior.id)){
                    prior.verify(policyCallerUser,id,sha256,prior.sequence,inventory);admitted=prior;
                    if(utilities().reconcileTerminal(policyCallerUser)||Boolean.TRUE.equals(old.get("terminal")))
                        return "ok=1\nresultCategory=ADMITTED_TERMINAL\nrequestId="+id+"\nack="+utilities().ack(policyCallerUser,id);
                }
                else if(!Boolean.TRUE.equals(old.get("terminal"))){
                    // A committed policy may have lost only the terminal root ACK.
                    byte[] oldPolicy=mAppPolicies.disk.read("policy-request.json");
                    Map<String,Object> completed=oldPolicy.length==0?new HashMap<>():PolicyJson.object(PolicyJson.parse(oldPolicy));
                    if(!utilities().reconcileTerminal(prior.user)&&(!prior.id.equals(completed.get("id"))||!completed.containsKey("result")))return requestRefused(policyCallerUser,id,"request_busy");
                }
            }
            if ("policy".equals(request.command)) {
                if(mAppPolicies!=null&&new SettingsBackup(mAppPolicies).busy())return requestRefused(policyCallerUser,id,"settings_recovery_required");
                if (mAppPolicies == null) return requestRefused(policyCallerUser,id,"policy_store_unavailable");
                java.util.Map<String,Object> policy = PolicyJson.object(PolicyJson.parse(java.util.Base64.getDecoder().decode(request.mode)));
                if (PolicyJson.integer(policy.get("userId")) != policyCallerUser) return requestRefused(policyCallerUser,id,"policy_user_mismatch");
                byte[] previous = mAppPolicies.disk.read("policy-request.json");
                byte[] retainedIdentity=mAppPolicies.disk.read("policy-request-"+id+".json");
                if(retainedIdentity.length!=0){
                    Map<String,Object> retained=PolicyJson.object(PolicyJson.parse(retainedIdentity));
                    RequestIdentity prior=RequestIdentity.read(retained.get("identity"));
                    prior.verify(policyCallerUser,id,sha256,prior.sequence,inventory);admitted=prior;
                }
                if (previous.length != 0) {
                    java.util.Map<String,Object> old = PolicyJson.object(PolicyJson.parse(previous));
                    if(id.equals(old.get("id"))){
                        if(old.containsKey("identity")){RequestIdentity prior=RequestIdentity.read(old.get("identity"));
                            prior.verify(policyCallerUser,id,sha256,prior.sequence,inventory);admitted=prior;
                        }else{
                            // Explicit V79 migration: only its proven primary admission is adoptable.
                            PolicyJson.require(policyCallerUser==0&&PolicyJson.integer(PolicyJson.object(old.get("payload")).get("userId"))==0
                                    &&sha256.equals(old.get("sha")),"legacy primary admission");
                            old.put("identity",admitted.json());previous=PolicyJson.bytes(old);mAppPolicies.disk.write("policy-request.json",previous);
                        }
                    }
                    if (!id.equals(old.get("id")) && !old.containsKey("result")) return requestRefused(policyCallerUser,id,"policy_request_busy");
                    if (id.equals(old.get("id")) && !sha256.equals(old.get("sha"))) return requestRefused(policyCallerUser,id,"policy_request_conflict");
                    if (!id.equals(old.get("id"))) {
                        String receipt = "policy-request-" + PolicyJson.string(old.get("id")) + ".json";
                        byte[] retained = mAppPolicies.disk.read(receipt);
                        PolicyJson.require(retained.length == 0 || Arrays.equals(retained, previous), "request evidence conflict");
                        if (retained.length == 0) mAppPolicies.disk.write(receipt, previous);
                        previous = new byte[0];
                    }
                }
                if (previous.length == 0) mAppPolicies.disk.write("policy-request.json",retainedIdentity.length!=0?retainedIdentity:
                        PolicyJson.bytes(PolicyJson.map("id", id, "sha", sha256, "payload", policy,"identity",admitted.json())));
            } else if ("set_uperf_mode".equals(request.command) || "set_uperf_app".equals(request.command) || "remove_uperf_app".equals(request.command)) {
                return requestRefused(policyCallerUser,id,"unified_policy_generation_required");
            }
            // A retry must not revoke the exact token still owned by the running
            // finite worker. Stopped/lost workers receive the normal recovery kick.
            String activeToken=SystemProperties.get(PROP_COMMAND_SEQ, "");
            if(id.equals(SystemProperties.get(PROP_COMMAND_ID, ""))
                    &&sha256.equals(SystemProperties.get(PROP_COMMAND_SHA256, ""))
                    &&activeToken.startsWith("u"+policyCallerUser+"_"+admitted.sequence+"_")
                    &&"running".equals(SystemProperties.get("init.svc.zui_control_request", "")))
                return "ok=1\nresultCategory=INDETERMINATE_OR_IN_PROGRESS\nrequestId="+id+"\ncommandSeq="+activeToken;
            if(rulesWriter(request.command))invalidateRulesObservation();
            mAppPolicies.disk.write("control-admission.json",PolicyJson.bytes(PolicyJson.map("identity",admitted.json(),"terminal",false)));
            String token="u"+policyCallerUser+"_"+admitted.sequence+"_"+Long.toHexString(SystemClock.elapsedRealtimeNanos());
            if (!id.equals(SystemProperties.get(PROP_COMMAND_ID, ""))) {
                SystemProperties.set(PROP_COMMAND_ID, id);
            }
            if (!sha256.equals(SystemProperties.get(PROP_COMMAND_SHA256, ""))) {
                SystemProperties.set(PROP_COMMAND_SHA256, sha256);
            }
            SystemProperties.set(PROP_COMMAND_SEQ, token);
            long sequenceSetNanos = SystemClock.elapsedRealtimeNanos();
            Log.i(TIMING_TAG, "id=" + id + " phase=T2 ns=" + sequenceSetNanos);
            Log.i(TAG, "control_request_kick id=" + id + " sha256="
                    + sha256.substring(0, 12) + " token=" + token);
            return "ok=1\nresultCategory=INDETERMINATE_OR_IN_PROGRESS\nrequestId=" + id + "\ncommandSeq=" + token;
        } catch (Exception e) {
            return "ok=0\nerror=policy_request:" + e.getClass().getSimpleName()+"\nresultCategory=INDETERMINATE_OR_IN_PROGRESS";
        } finally {
            Binder.restoreCallingIdentity(identity);
        }
    }

    private Profile makeProfile(String pkg, int userId, int displayHz, int fpsCap, String mode) {
        String cleanMode = normalizeMode(mode);
        if (cleanMode == null) {
            mLastError = "invalid_mode";
            return null;
        }
        if (!isDisplayHzSupported(displayHz)) {
            mLastError = "unsupported_display_hz_" + displayHz;
            return null;
        }
        if (fpsCap < 0 || fpsCap > 240) {
            mLastError = "invalid_fps_cap";
            return null;
        }
        return new Profile(pkg, userId, displayHz, fpsCap, cleanMode);
    }

    private Profile focusedProfile(){
        return mRawFocusTransient || mImeVisible || mRawFocusedPackage.isEmpty()
                || isTransientPackage(mRawFocusedPackage)
                ? neutralProfile(mRawFocusedUserId)
                : profileFor(mRawFocusedPackage, mRawFocusedUserId);
    }
    private String reconcileFocusedProfile(String reason, boolean force) {
        return applyProfile(focusedProfile(), reason, force);
    }

    private String applyProfile(Profile profile, String reason, boolean force) {
        mDesiredScenePackage = profile.packageName;
        mTargetDisplayHz = profile.displayHz;
        mTargetFpsCap = profile.fpsCap;
        mTargetMode = profile.mode;
        if (mRefreshDisabled || readRefreshDisableMask() != 0) {
            if (mRefreshDisabled && hasResidualRefreshOwnership()) {
                scheduleDisableReleaseRetry();
            }
            if (mLastApplyError.isEmpty()) {
                mLastApplyReason = reason + ":disabled";
            }
            return "disabled";
        }
        ModeMatch match = findMode(profile.displayHz, mRawFocusedDisplayId);
        if (match == null) {
            return failApplyBeforeMutation(reason, "no_display_mode_" + profile.displayHz);
        }
        DisplayManagerInternal dmi = LocalServices.getService(DisplayManagerInternal.class);
        if (dmi == null) {
            return failApplyBeforeMutation(reason, "DisplayManagerInternal_unavailable");
        }
        if (!force && mAppRequestOwned && mRenderVoteOwned
                && mRenderVoteHz == profile.displayHz
                && mLastAppliedDisplayId == match.displayId
                && mLastAppliedModeId == match.modeId
                && mLastAppliedDisplayHz == profile.displayHz) {
            mAppliedScenePackage = profile.packageName;
            mAppliedDisplayHz = profile.displayHz;
            mSkipSameCount++;
            mLastApplyError = "";
            mLastError = "";
            mLastApplyReason = reason + ":display=" + match.displayId
                    + ":mode=" + match.modeId + ":skipSame";
            return "skipSame";
        }

        mAttemptedScenePackage = profile.packageName;
        mAttemptedDisplayHz = profile.displayHz;
        int peakHz;
        try {
            peakHz = syncPeakRefreshRate(profile.displayHz);
        } catch (Throwable t) {
            return failApplyAfterMutation(reason, "peak:" + throwableText(t), false);
        }
        try {
            applyGlobalRenderVote(dmi, profile.displayHz);
        } catch (Throwable t) {
            return failApplyAfterMutation(reason, "renderVote:" + throwableText(t), false);
        }
        try {
            dmi.setDisplayProperties(match.displayId, true, profile.displayHz,
                    match.modeId, 0.0f, profile.displayHz, false, false, false);
            mAppRequestOwned = true;
            mAppRequestHandoff = "active";
            mAppRequestHandoffPending = false;
            mLastAppliedDisplayId = match.displayId;
            mLastAppliedModeId = match.modeId;
            mLastAppliedDisplayHz = profile.displayHz;
            mAppliedScenePackage = profile.packageName;
            mAppliedDisplayHz = profile.displayHz;
            mRefreshApplyCount++;
            mLastApplyError = "";
            mLastError = "";
            mLastApplyReason = reason + ":display=" + match.displayId
                    + ":mode=" + match.modeId + ":peakBridge=" + peakHz + ":applied";
            return "applied";
        } catch (Throwable t) {
            Log.w(TAG, "apply display failed", t);
            return failApplyAfterMutation(reason, "appRequest:" + throwableText(t), true);
        }
    }

    private String failApplyBeforeMutation(String reason, String error) {
        mLastApplyError = error;
        mLastError = error;
        mLastApplyReason = reason + ":failedBeforeMutation";
        return "failed";
    }

    private String failApplyAfterMutation(String reason, String error,
            boolean appRequestMayHaveChanged) {
        StringBuilder cleanupError = new StringBuilder();
        if (!clearGlobalRenderVote()) {
            cleanupError.append(";renderVoteReleaseFailed");
        }
        if (!releasePeakBridge()) {
            cleanupError.append(";peakRestoreFailed");
        }
        if ((appRequestMayHaveChanged || mAppRequestOwned)
                && !requestWindowManagerHandoff("applyFailure")) {
            cleanupError.append(";appRequestHandoffFailed");
        }
        clearAppliedState();
        mLastApplyError = error + cleanupError;
        mLastError = mLastApplyError;
        mLastApplyReason = reason + ":failedAfterMutation";
        return "failed";
    }

    private int syncPeakRefreshRate(int targetHz) {
        int peakHz = targetHz > 120 ? targetHz : 120;
        String desired = peakHz + ".0";
        String current = readPeakSetting();
        if (desired.equals(current)) {
            if (mPeakBridgeOwned && !desired.equals(mPeakLastWritten)) {
                clearPeakOwnership("externalAlreadyDesired");
            }
            mLastSyncedPeakHz = peakHz;
            return peakHz;
        }
        boolean acquireOwnership = !mPeakBridgeOwned;
        String restoreValue = current;
        String previousLastWritten = mPeakLastWritten;
        if (!acquireOwnership && !safe(mPeakLastWritten).equals(current)) {
            mPeakRestoreValue = current;
        }
        if (acquireOwnership) {
            mPeakBridgeOwned = true;
            mPeakRestoreValue = restoreValue;
        }
        mPeakLastWritten = desired;
        mPeakReleaseStatus = "applyPending";
        try {
            if (!writePeakSetting(desired)) {
                throw new IllegalStateException("peak_write_rejected");
            }
        } catch (RuntimeException e) {
            try {
                if (!desired.equals(readPeakSetting())) {
                    if (acquireOwnership) {
                        clearPeakOwnership("writeNotObserved");
                    } else {
                        mPeakLastWritten = previousLastWritten;
                        mPeakReleaseStatus = "writeNotObserved";
                    }
                }
            } catch (Throwable ignored) {
            }
            throw e;
        }
        mPeakReleaseStatus = "active";
        mLastSyncedPeakHz = peakHz;
        return peakHz;
    }

    private String readPeakSetting() {
        long token = Binder.clearCallingIdentity();
        try {
            // OEM DisplayModeDirector reads its system resolver user, not current user.
            return getSettingForUser(
                    SETTING_PEAK_REFRESH_RATE,0);
        } finally {
            Binder.restoreCallingIdentity(token);
        }
    }

    private boolean writePeakSetting(String value) {
        long token = Binder.clearCallingIdentity();
        try {
            return putSettingForUser(
                    SETTING_PEAK_REFRESH_RATE, value,0);
        } finally {
            Binder.restoreCallingIdentity(token);
        }
    }

    private boolean releasePeakBridge() {
        if (!mPeakBridgeOwned) {
            mLastSyncedPeakHz = -1;
            mPeakReleaseStatus = "notOwned";
            return true;
        }
        try {
            String current = readPeakSetting();
            if (safe(mPeakLastWritten).equals(current)) {
                if (!writePeakSetting(mPeakRestoreValue)) {
                    mPeakReleaseStatus = "restoreRejected";
                    return false;
                }
                mPeakReleaseStatus = "restored";
            } else {
                mPeakReleaseStatus = "externalPreserved";
            }
            clearPeakOwnership(mPeakReleaseStatus);
            return true;
        } catch (Throwable t) {
            mPeakReleaseStatus = "restoreFailed:" + throwableText(t);
            Log.w(TAG, "peak bridge release failed", t);
            return false;
        }
    }

    private void clearPeakOwnership(String releaseStatus) {
        mPeakBridgeOwned = false;
        mPeakRestoreValue = null;
        mPeakLastWritten = "";
        mLastSyncedPeakHz = -1;
        mPeakReleaseStatus = releaseStatus;
    }

    private void registerPeakObserver() {
        try {
            mContext.getContentResolver().registerContentObserver(
                    Settings.System.getUriFor(SETTING_PEAK_REFRESH_RATE),
                    false,
                    new ContentObserver(mWorker) {
                        @Override
                        public void onChange(boolean selfChange) {
                            onPeakRefreshRateChanged();
                        }
                    });
        } catch (Throwable t) {
            Log.w(TAG, "peak observer unavailable", t);
        }
    }

    private void registerRefreshPropertyObserver() {
        try {
            SystemProperties.addChangeCallback(new Runnable() {
                @Override
                public void run() {
                    enqueueRefreshDisableMask(readRefreshDisableMask());
                }
            });
            enqueueRefreshDisableMask(readRefreshDisableMask());
        } catch (Throwable t) {
            mLastApplyError = "propertyObserver:" + throwableText(t);
            Log.w(TAG, "refresh property observer unavailable", t);
        }
    }

    private void enqueueRefreshDisableMask(final int disableMask) {
        synchronized (mRefreshPropertyLock) {
            if (disableMask == mObservedRefreshDisableMask) {
                return;
            }
            mObservedRefreshDisableMask = disableMask;
            mWorker.post(new Runnable() {
                @Override
                public void run() {
                    onRefreshPropertiesChanged(disableMask);
                }
            });
        }
    }

    private synchronized void onRefreshPropertiesChanged(int observedMask) {
        refreshMonitor();
        int disableMask = readRefreshDisableMask();
        mUperfScenePolicy.refreshGpu();
        synchronized (mRefreshPropertyLock) {
            mObservedRefreshDisableMask = disableMask;
        }
        if (disableMask == mRefreshDisableMask) {
            return;
        }
        boolean wasDisabled = mRefreshDisabled;
        mRefreshDisableMask = disableMask;
        boolean disabled = disableMask != 0;
        mRefreshDisabled = disabled;
        if (!wasDisabled && disabled) {
            if (!releaseRefreshOwnership("propertyDisable")) {
                scheduleDisableReleaseRetry();
            }
        } else if (wasDisabled && !disabled) {
            if (latestFocusMatchesRaw()) {
                reconcileFocusedProfile("propertyEnable", true);
            } else {
                mLastApplyReason = "propertyEnable:focusPending";
                mWorker.post(new Runnable() {
                    @Override
                    public void run() {
                        reconcileAfterPropertyEnable();
                    }
                });
            }
        } else {
            if (disabled && hasResidualRefreshOwnership()) {
                if (!releaseRefreshOwnership("propertyDisableMaskChanged:" + disableMask)) {
                    scheduleDisableReleaseRetry();
                }
            } else {
                mLastApplyReason = "propertyDisableMaskChanged:" + disableMask;
            }
        }
        publishState();
    }

    private synchronized void reconcileAfterPropertyEnable() {
        if (mRefreshDisabled) {
            return;
        }
        if (latestFocusMatchesRaw()) {
            reconcileFocusedProfile("propertyEnableAfterFocus", true);
            publishState();
        }
    }

    private boolean latestFocusMatchesRaw() {
        FocusSnapshot latestFocus = mLatestFocus;
        return !mLatestWindowFocusEmpty
                && latestFocus.packageName.equals(mRawFocusedPackage)
                && latestFocus.userId == mRawFocusedUserId
                && resolveDisplayId(latestFocus.displayId) == mRawFocusedDisplayId
                && latestFocus.transientFocus == mRawFocusTransient;
    }

    private boolean hasResidualRefreshOwnership() {
        return mRenderVoteOwned || mPeakBridgeOwned || mAppRequestOwned;
    }

    private synchronized void scheduleDisableReleaseRetry() {
        if (mDisableReleaseRetryPosted) {
            return;
        }
        mDisableReleaseRetryPosted = true;
        mWorker.post(new Runnable() {
            @Override
            public void run() {
                retryDisabledRelease();
            }
        });
    }

    private synchronized void retryDisabledRelease() {
        mDisableReleaseRetryPosted = false;
        if (mRefreshDisabled && hasResidualRefreshOwnership()) {
            releaseRefreshOwnership("propertyDisableRetry");
            publishState();
        }
    }

    private static int readRefreshDisableMask() {
        int mask = SystemProperties.getBoolean(PROP_GLOBAL_DISABLE, false) ? 1 : 0;
        return SystemProperties.getBoolean(PROP_REFRESH_DISABLE, false) ? mask | 2 : mask;
    }

    private void registerScreenObserver() {
        try {
            PowerManager power = (PowerManager) mContext.getSystemService(PowerManager.class);
            mScreenInteractive = power == null || power.isInteractive();
            IntentFilter filter = new IntentFilter();
            filter.addAction(Intent.ACTION_SCREEN_ON);
            filter.addAction(Intent.ACTION_SCREEN_OFF);
            filter.addAction(Intent.ACTION_USER_PRESENT);
            filter.addAction(Intent.ACTION_POWER_CONNECTED);
            filter.addAction(Intent.ACTION_POWER_DISCONNECTED);
            filter.addAction(Intent.ACTION_BATTERY_CHANGED);
            mContext.registerReceiver(new BroadcastReceiver() {
                @Override
                public void onReceive(Context context, Intent intent) {
                    String action = intent == null ? "" : intent.getAction();
                    if (Intent.ACTION_SCREEN_ON.equals(action)) {
                        onScreenInteractiveChanged(true);
                    } else if (Intent.ACTION_SCREEN_OFF.equals(action)) {
                        onScreenInteractiveChanged(false);
                    } else if (Intent.ACTION_POWER_CONNECTED.equals(action) || Intent.ACTION_POWER_DISCONNECTED.equals(action)) {
                        mMonitor.invalidatePower(Intent.ACTION_POWER_CONNECTED.equals(action));
                    } else if (Intent.ACTION_BATTERY_CHANGED.equals(action)) {
                        mMonitor.onBatteryStateChanged(intent);
                    } else if (Intent.ACTION_USER_PRESENT.equals(action)) {
                        beginMonitorUnlockRecheck();
                    }
                }
            }, filter, null, mWorker);
        } catch (Throwable t) {
            Log.w(TAG, "screen observer unavailable", t);
        }
    }

    private synchronized void cancelMonitorUnlockRecheck() {
        mMonitorUnlockEpoch++;
        if(mMonitorUnlockRecheck!=null)mWorker.removeCallbacks(mMonitorUnlockRecheck);
        mMonitorUnlockRecheck=null;
    }

    private synchronized void beginMonitorUnlockRecheck() {
        cancelMonitorUnlockRecheck();
        refreshMonitor();
        final long ticket=mMonitorUnlockEpoch,deadline=SystemClock.elapsedRealtime()+2000;
        mMonitorUnlockRecheck=()->{
            synchronized(ZuiControlService.this){
                if(ticket!=mMonitorUnlockEpoch)return;
                PowerManager power=mContext.getSystemService(PowerManager.class);
                android.app.KeyguardManager lock=mContext.getSystemService(android.app.KeyguardManager.class);
                boolean interactive=power!=null&&power.isInteractive();
                boolean locked=lock==null||lock.isKeyguardLocked();
                mMonitor.traceUnlock(interactive,locked);
                if(!mScreenInteractive||!interactive){cancelMonitorUnlockRecheck();refreshMonitor();return;}
                if(!locked){mMonitorUnlockRecheck=null;refreshMonitor();return;}
                long remaining=deadline-SystemClock.elapsedRealtime();
                if(remaining<=0){mMonitorUnlockRecheck=null;return;}
                mWorker.postDelayed(mMonitorUnlockRecheck,Math.min(150,remaining));
            }
        };
        mMonitorUnlockRecheck.run();
    }

    private synchronized void onScreenInteractiveChanged(boolean interactive) {
        if (mScreenInteractive == interactive) {
            if(interactive)beginMonitorUnlockRecheck();else cancelMonitorUnlockRecheck();
            return;
        }
        mScreenInteractive = interactive;
        if(interactive)beginMonitorUnlockRecheck();
        else {cancelMonitorUnlockRecheck();refreshMonitor();}
        mUperfScenePolicy.onInteractiveChanged(interactive,
                interactive ? "screenOn" : "screenOff", SystemClock.elapsedRealtimeNanos());
        publishState();
    }

    private synchronized void onPeakRefreshRateChanged() {
        if (mRefreshDisabled || !mAppRequestOwned || mAppliedDisplayHz <= 0) {
            return;
        }
        if (!isPeakRefreshRateSynced(mAppliedDisplayHz)) {
            try {
                int peakHz = syncPeakRefreshRate(mAppliedDisplayHz);
                mLastApplyError = "";
                mLastError = "";
                mLastApplyReason = "peakObserver:target=" + mAppliedDisplayHz
                        + ":peakBridge=" + peakHz;
                publishState();
            } catch (Throwable t) {
                mLastApplyError = "peakObserver:" + throwableText(t);
                mLastError = mLastApplyError;
                mLastApplyReason = "peakObserver:failed";
                publishState();
            }
        }
    }

    private boolean isPeakRefreshRateSynced(int targetHz) {
        int peakHz = targetHz > 120 ? targetHz : 120;
        String desired = peakHz + ".0";
        return desired.equals(readPeakSetting());
    }

    private boolean releaseRefreshOwnership(String reason) {
        boolean renderVoteReleased = clearGlobalRenderVote();
        boolean peakReleased = releasePeakBridge();
        boolean hadAppRequest = mAppRequestOwned;
        boolean appRequestReleased = !hadAppRequest
                || requestWindowManagerHandoff(reason);
        if (!mAppRequestOwned && appRequestReleased
                && !mAppRequestHandoff.startsWith("requested:")) {
            mAppRequestHandoff = "notOwned";
        }
        clearAppliedState();
        if (appRequestReleased && renderVoteReleased && peakReleased) {
            String priorApplyError = mLastApplyError;
            mLastApplyError = "";
            if (mLastError.equals(priorApplyError)) {
                mLastError = "";
            }
            mLastApplyReason = reason + (hadAppRequest
                    ? ":releaseRequested" : ":released");
            return true;
        }
        mLastApplyError = (!appRequestReleased ? "appRequest_handoff_failed" : "")
                + (!renderVoteReleased ? (appRequestReleased ? "" : ";")
                + "render_vote_release_failed" : "")
                + (!peakReleased ? (appRequestReleased && renderVoteReleased ? "" : ";")
                + "peak_restore_failed" : "");
        mLastError = mLastApplyError;
        mLastApplyReason = reason + ":releasePartial";
        return false;
    }

    private boolean requestWindowManagerHandoff(String reason) {
        try {
            WindowManagerInternal wmi = LocalServices.getService(WindowManagerInternal.class);
            if (wmi == null) {
                mAppRequestHandoff = "failed:WindowManagerInternal_unavailable";
                return false;
            }
            wmi.requestTraversalFromDisplayManager();
            mAppRequestOwned = false;
            mAppRequestHandoff = "requested:" + reason;
            mAppRequestHandoffPending = true;
            return true;
        } catch (Throwable t) {
            mAppRequestHandoff = "failed:" + throwableText(t);
            Log.w(TAG, "WindowManager AppRequest handoff failed", t);
            return false;
        }
    }

    private void clearAppliedState() {
        mAppliedScenePackage = "";
        mAppliedDisplayHz = 0;
        mLastAppliedDisplayId = -1;
        mLastAppliedModeId = -1;
        mLastAppliedDisplayHz = -1;
    }

    private static String throwableText(Throwable t) {
        return t.getClass().getSimpleName() + ":" + safe(t.getMessage());
    }

    private Profile profileFor(String pkg, int userId) {
        if (!mPolicyReady) return neutralProfile(userId);
        Profile profile = mProfiles.get(key(userId, pkg));
        if (profile != null) {
            return profile;
        }
        Profile fallback = defaultProfile(userId);
        return "default".equals(pkg) ? fallback
                : new Profile(pkg, userId, fallback.displayHz, fallback.fpsCap, fallback.mode);
    }

    private Profile defaultProfile(int userId) {
        if (mPolicyReady && mAppPolicies != null && mAppPolicies.current != null) return new Profile(DEFAULT_SCENE, userId,
                mAppPolicies.current.global(userId).refreshHz, 0, "DISPLAY_ONLY");
        return neutralProfile(userId);
    }

    private Profile neutralProfile(int userId) {
        return new Profile(DEFAULT_SCENE, userId, 120, 0, "DISPLAY_ONLY");
    }

    private boolean isDefaultEquivalent(Profile profile) {
        Profile fallback = defaultProfile(profile.userId);
        return profile.displayHz == fallback.displayHz
                && profile.fpsCap == fallback.fpsCap
                && profile.mode.equals(fallback.mode);
    }

    private void loadProfiles() {
        mProfiles.clear();
        mGpuOverrides.clear();
        mGpuGlobalRanges.clear();
        mMonitorApps.clear();
        try {
            byte[] raw = mProfileFile.readFully();
            String text = new String(raw, StandardCharsets.UTF_8);
            for (String line : text.split("\n")) {
                line = line.trim();
                if (line.isEmpty() || line.startsWith("#") || line.startsWith("version=")) {
                    continue;
                }
                String[] parts = line.split("\\|");
                if (parts.length == 3 && "monitor".equals(parts[0])) {
                    int user = parseInt(parts[1], -1);
                    if (user >= 0 && validPackage(parts[2]) && !isTransientPackage(parts[2])) {
                        mMonitorApps.add(key(user, parts[2]));
                    }
                    continue;
                }
                if (parts.length == 5 && "gpuGlobal".equals(parts[0])) {
                    try {
                        int user = Integer.parseInt(parts[1]);
                        if (user >= 0 && isUperfMode(parts[2])) {
                            mGpuGlobalRanges.put(key(user, parts[2]), new GpuRange(
                                    Integer.parseInt(parts[3]), Integer.parseInt(parts[4])));
                        }
                    } catch (IllegalArgumentException badRange) {
                        Log.w(TAG, "Ignoring invalid persisted global GPU range");
                    }
                    continue;
                }
                if (parts.length == 5 && "gpu".equals(parts[0])) {
                    try {
                        int user = Integer.parseInt(parts[1]);
                        if (user >= 0 && validPackage(parts[2]) && !isGpuTransientPackage(parts[2])) {
                            mGpuOverrides.put(key(user, parts[2]), new GpuRange(
                                    Integer.parseInt(parts[3]), Integer.parseInt(parts[4])));
                        }
                    } catch (IllegalArgumentException badRange) {
                        Log.w(TAG, "Ignoring invalid persisted GPU range");
                    }
                    continue;
                }
                Profile p = null;
                if (parts.length == 5 && "default".equals(parts[0])) {
                    p = neutralProfile(parseInt(parts[1], 0));
                } else if (parts.length == 6 && "pkg".equals(parts[0])) {
                    if (!isTransientPackage(parts[2])) {
                        p = makeProfile(parts[2], parseInt(parts[1], 0),
                                parseInt(parts[3], 120), parseInt(parts[4], 0), parts[5]);
                    }
                }
                if (p != null && ("default".equals(p.packageName) || !isDefaultEquivalent(p))) {
                    mProfiles.put(key(p.userId, p.packageName), p);
                }
            }
        } catch (Throwable t) {
            mLastError = "profile_load:" + t.getClass().getSimpleName();
        }
        if (!mProfiles.containsKey(key(0, "default"))) {
            mProfiles.put(key(0, "default"), defaultProfile(0));
        }
    }

